import assert from 'node:assert/strict';
import {build,preview} from 'vite';
import {chromium} from '@playwright/test';
import {resolve,join} from 'node:path';
import {writeFile,mkdir} from 'node:fs/promises';
import {craftCompiler} from '../../dist/libs/compiler/src/vite.js';
const root=resolve(import.meta.dirname,'../..');
const init=()=>({indexCreated:0,indexReads:0,binds:0,bindingInstalls:0,effectCreated:0,effectStoppedInitially:0,dom:{},attributes:{},sameAttributeWrites:0,sameTextWrites:0});
function patch(code,old,next){assert.equal(code.split(old).length,2,old);return code.replace(old,next);}
const plugin={name:'allocation-counts',enforce:'pre',transform(code,id){
 if(id.endsWith('/libs/component/src/lib/render/interpreter.ts')) {
  code=patch(code,'return ɵsettledReader(read) as InputValue<number>;','(globalThis as any).__nextPerf.indexCreated++; return ɵsettledReader(() => { (globalThis as any).__nextPerf.indexReads++; return read(); }) as InputValue<number>;');
  code=patch(code,'const readers = plan.bind(inputs);','(globalThis as any).__nextPerf.binds++; (globalThis as any).__nextPerf.bindingInstalls += plan.bindings.length; const readers = plan.bind(inputs);');
  return code;
 }
 if(id.endsWith('/libs/core/src/lib/host/craft-signal.ts')) {
  code=patch(code,'export function ɵcraftBindingEffect(fn: () => void): (() => void) | undefined {','export function ɵcraftBindingEffect(fn: () => void): (() => void) | undefined { (globalThis as any).__nextPerf.effectCreated++;');
  code=patch(code,'if (node !== undefined && node.deps === undefined) {','if (node !== undefined && node.deps === undefined) { (globalThis as any).__nextPerf.effectStoppedInitially++;');
  return code;
 }
 if(id.endsWith('/libs/core/src/lib/host/craft-dom.ts')) {
  code=patch(code,'  return {','  const adapter: CraftDomAdapter = {');
  code=patch(code,'\n  };\n}','\n  };\n return new Proxy(adapter, { get(target, key) { const value = Reflect.get(target,key); if (typeof value !== "function") return value; return (...args: any[]) => { const counts=(globalThis as any).__nextPerf; counts.dom[key]=(counts.dom[key]??0)+1; if(key === "setAttribute") {counts.attributes[args[1]]=(counts.attributes[args[1]]??0)+1; if(args[0].getAttribute(args[1])===args[2]) counts.sameAttributeWrites++;} if(key === "setValue" && args[0].nodeValue === args[1]) counts.sameTextWrites++; return value.apply(target,args); }; } });\n}');
  return code;
 }
}};
const browser=await chromium.launch({headless:true});
const result=[];
try {
for(const kind of ['micro','page']) {
 const app=join(root,kind==='micro'?'apps/compiler-benchmark':'apps/framework-benchmark');
 const outDir=join(root,'tmp/next-perf/counts-dist',kind); await mkdir(outDir,{recursive:true});
 await build({configFile:false,root:app,logLevel:'error',plugins:[plugin,craftCompiler({lean:true})],resolve:{alias:[{find:'@craft-ts/component/compiler-runtime',replacement:join(root,'libs/component/src/compiler-runtime.ts')},...['core','component','style'].map(name=>({find:'@craft-ts/'+name,replacement:join(root,'libs/'+name+'/src/index.ts')}))]},build:{outDir,emptyOutDir:true,minify:false,rolldownOptions:{input:join(app,kind==='micro'?'index.html':'craft-page/index.html')}}});
 const server=await preview({configFile:false,root:app,logLevel:'error',build:{outDir},preview:{host:'127.0.0.1',port:0}});
 try {
 for(const variant of kind==='micro'?['rows','indexed']:['page']) {
  const context=await browser.newContext(),page=await context.newPage(),errors=[];
  page.on('pageerror',e=>errors.push(e.message)); await page.addInitScript(`globalThis.__nextPerf=(${init})();`);
  const url=`http://127.0.0.1:${server.httpServer.address().port}/`+(kind==='micro'?`?case=${variant}&rows=1000`:'craft-page/?scale=2');
  await page.goto(url);
  await page.waitForFunction(kind==='micro'?()=>window.__compilerBench?.ready:()=>Number.isFinite(window.__bench?.bootstrapMs));
  const stages=[{phase:'mount',counts:await page.evaluate(()=>structuredClone(window.__nextPerf))}];
  for(const phase of kind==='micro'?['update-one','reverse','filter','restore']:['toggle-one','counter','theme','filter','unfilter','sort']) {
   await page.evaluate(`globalThis.__nextPerf=(${init})();`);
   await page.evaluate(({phase,kind})=>(kind==='micro'?window.__compilerBench:window.__bench).run(phase === 'unfilter' ? 'filter' : phase),{phase,kind});
   stages.push({phase,counts:await page.evaluate(()=>structuredClone(window.__nextPerf))});
  }
  assert.deepEqual(errors,[]);result.push({variant,stages});await context.close();
 }
 }finally{await new Promise(resolve=>server.httpServer.close(resolve));}
}
}finally{await browser.close();}
await writeFile(join(root,'tmp/next-perf/counts.json'),JSON.stringify({note:'Instrumented diagnostic counts, not timings. Source libraries unchanged.',result},null,2)+'\n');
console.log(JSON.stringify(result,null,2));

methods.profileScript:
// Named CPU samples for the realistic page, separate from timing builds.
// npm run compiler:build
// COMPILER_PROFILE_LIB_ROOT=/frozen/runtime node apps/compiler-benchmark/profile.mjs
import assert from 'node:assert/strict';
import { build, preview } from 'vite';
import { chromium } from '@playwright/test';
import { join, resolve } from 'node:path';
import { writeFile, mkdir, readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { createHash } from 'node:crypto';
import { craftCompiler } from '../../dist/libs/compiler/src/vite.js';
const root = resolve(fileURLToPath(new URL('../..', import.meta.url))),
  app = join(root, 'apps/framework-benchmark');
const output = resolve(
  root,
  process.env.COMPILER_PROFILE_OUTPUT ?? 'tmp/compiler-profile',
);
const libraryRoot = resolve(root, process.env.COMPILER_PROFILE_LIB_ROOT ?? '.');
const runs = Number(process.env.COMPILER_PROFILE_RUNS ?? 3),
  scale = Number(process.env.COMPILER_PROFILE_SCALE ?? 2),
  cpu = Number(process.env.COMPILER_PROFILE_CPU ?? 4);
assert(
  Number.isInteger(runs) && runs > 0 && [1, 2, 4].includes(scale) && cpu >= 1,
);
await mkdir(output, { recursive: true });
const sourceSha256 = Object.fromEntries(
  await Promise.all(
    [
      'libs/component/src/lib/render/interpreter.ts',
      'libs/core/src/lib/lifecycle.ts',
      'libs/core/src/lib/craft-generator-runtime.ts',
    ].map(async (file) => [
      file,
      createHash('sha256')
        .update(await readFile(join(libraryRoot, file)))
        .digest('hex'),
    ]),
  ),
);

await build({
  configFile: false, root: app,
  logLevel: 'error',
  plugins: [
    // COMPILER_PROFILE_OPTIONS='{"lean":true}' profiles another compiler mode.
    craftCompiler(JSON.parse(process.env.COMPILER_PROFILE_OPTIONS ?? '{}')),
    {
      name: 'profile-gate',
      enforce: 'pre',
      transform(code, id) {
        if (id.endsWith('/src/craft-page/main.ts')) {
          assert.equal(code.split('begin();').length, 2);
          return code.replace(
            'begin();',
            'await new Promise<void>(resolve => { (globalThis as any).__releaseMount = resolve; });\nbegin();',
          );
        }
      },
    },
  ],
  resolve: {
    alias: [
      {
        find: '@craft-ts/component/compiler-runtime',
        replacement: join(
          libraryRoot,
          'libs/component/src/compiler-runtime.ts',
        ),
      },
      ...['core', 'component', 'style'].map((name) => ({
        find: '@craft-ts/' + name,
        replacement: join(libraryRoot, 'libs/' + name + '/src/index.ts'),
      })),
    ],
  },
  build: {
    outDir: join(output, 'profile-dist'),
    emptyOutDir: true,
    minify: false,
    sourcemap: true,
    rolldownOptions: {
      input: { 'craft-page': join(app, 'craft-page/index.html') },
    },
  },
});
const server = await preview({
    configFile: false, root: app,
    logLevel: 'error',
    build: { outDir: join(output, 'profile-dist') }, preview: { host: '127.0.0.1', port: 0 },
  }),
  browser = await chromium.launch({ headless: true }),
  report = [];
try {
  for (let run = 0; run < runs; run++) {
    const context = await browser.newContext({
        viewport: { width: 1280, height: 800 },
      }),
      page = await context.newPage(),
      errors = [];
    page.on('pageerror', (e) => errors.push(e.message));
    const cdp = await context.newCDPSession(page);
    await cdp.send('Emulation.setCPUThrottlingRate', { rate: cpu });
    await page.goto(
      `http://127.0.0.1:${server.httpServer.address().port}/craft-page/?scale=${scale}`,
    );
    await page.waitForFunction(
      () => typeof globalThis.__releaseMount === 'function',
    );
    await cdp.send('Profiler.enable');
    await cdp.send('Profiler.setSamplingInterval', { interval: 100 });
    for (const phase of ['mount', 'theme', 'filter']) {
      await cdp.send('Profiler.start');
      if (phase === 'mount') {
        await page.evaluate(() => globalThis.__releaseMount());
        await page.waitForFunction(() =>
          Number.isFinite(window.__bench.bootstrapMs),
        );
      } else await page.evaluate((action) => window.__bench.run(action), phase);
      const { profile } = await cdp.send('Profiler.stop');
      await writeFile(
        join(output, `${phase}-${run}.cpuprofile`),
        JSON.stringify(profile),
      );
      const byId = new Map(profile.nodes.map((n) => [n.id, n])),
        totals = new Map();
      for (let i = 0; i < profile.samples.length; i++) {
        const frame = byId.get(profile.samples[i]).callFrame,
          key = JSON.stringify({
            name: frame.functionName,
            file: frame.url.split('/').pop(),
            line: frame.lineNumber + 1,
          });
        totals.set(
          key,
          (totals.get(key) ?? 0) + (profile.timeDeltas[i] ?? 0) / 1000,
        );
      }
      report.push({
        run,
        phase,
        self: [...totals]
          .map(([key, ms]) => ({ ...JSON.parse(key), ms }))
          .sort((a, b) => b.ms - a.ms),
      });
    }
    assert.deepEqual(errors, []);
    await context.close();
  }
} finally {
  await browser.close();
  await new Promise((done) => server.httpServer.close(done));
}
await writeFile(
  join(output, 'profile-summary.json'),
  JSON.stringify(
    {
      options: { runs, scale, cpu, libraryRoot },
      sourceSha256,
      profiles: report,
      note: 'Named samples in an unminified production build. Profiling and throttling overhead mean these are not timing comparisons or exact attribution percentages.',
    },
    null,
    2,
  ) + '\n',
);
for (const phase of ['mount', 'theme', 'filter']) {
  const totals = new Map();
  for (const row of report.filter((r) => r.phase === phase))
    for (const item of row.self) {
      const key = item.name + ' (' + item.line + ')';
      totals.set(key, (totals.get(key) ?? 0) + item.ms);
    }
  console.log(phase, [...totals].sort((a, b) => b[1] - a[1]).slice(0, 24));
}
